"""Main CLI entry point with Click group and subcommands."""

import click

from cli_tool.commands.greet import greet
from cli_tool.commands.process import process
from cli_tool.commands.generate import generate


@click.group(invoke_without_command=True)
@click.version_option(version="0.1.0", prog_name="cli-tool")
@click.pass_context
def cli(ctx):
    """cli-tool - A multi-command CLI application.

    Use --help on any subcommand for detailed usage information.
    """
    if ctx.invoked_subcommand is None:
        click.echo(ctx.get_help())


cli.add_command(greet)
cli.add_command(process)
cli.add_command(generate)


def main():
    cli()


if __name__ == "__main__":
    main()

"""Greet subcommand with options and arguments."""

import click


@click.command()
@click.argument("name")
@click.option(
    "-t",
    "--title",
    type=click.Choice(["Mr.", "Ms.", "Dr.", "Prof."], case_sensitive=False),
    default=None,
    help="Title to use before the name.",
)
@click.option(
    "-c",
    "--count",
    default=1,
    type=click.IntRange(min=1, max=100),
    help="Number of times to greet.",
)
@click.option(
    "-f",
    "--format",
    type=click.Choice(["text", "json"], case_sensitive=False),
    default="text",
    help="Output format.",
)
@click.option(
    "-v",
    "--verbose",
    is_flag=True,
    default=False,
    help="Print additional greeting details.",
)
@click.option(
    "--uppercase",
    is_flag=True,
    default=False,
    help="Convert output to uppercase.",
)
@click.pass_context
def greet(ctx, name, title, count, format, verbose, uppercase):
    """Greet someone by name with configurable options.

    NAME is the person to greet.

    Examples:
        cli-tool greet Alice
        cli-tool greet Alice --title Dr. --count 3
        cli-tool greet Bob --format json
    """
    greeting = f"Hello"
    if title:
        greeting = f"Hello {title} {name}"
    else:
        greeting = f"Hello {name}"

    if verbose:
        click.echo(f"[Greeting {count} time(s)]")

    for i in range(count):
        if count > 1:
            output = f"Greeting #{i + 1}: {greeting}"
        else:
            output = greeting

        if uppercase:
            output = output.upper()

        if format == "json":
            import json

            output = json.dumps({"greeting": output, "index": i + 1})

        click.echo(output)

"""Process subcommand with callback validation and file handling."""

import click
import os


def validate_size(ctx, param, value):
    """Custom callback to validate and normalize size values."""
    if value is None:
        return None
    size_str = str(value).strip().lower()
    multipliers = {"k": 1024, "m": 1048576, "g": 1073741824}
    if size_str and size_str[-1] in multipliers:
        try:
            number = float(size_str[:-1])
            return int(number * multipliers[size_str[-1]])
        except ValueError:
            raise click.BadParameter(
                f"Invalid size format: {value}. Use numbers with optional k/m/g suffix."
            )
    try:
        return int(value)
    except ValueError:
        raise click.BadParameter(
            f"Invalid size: {value}. Must be an integer or integer with suffix (e.g., 10k, 5m)."
        )


@click.command()
@click.argument("input_path", type=click.Path(exists=True, readable=True, dir_okay=False))
@click.option(
    "-o",
    "--output",
    type=click.Path(writable=True, dir_okay=False),
    default=None,
    help="Output file path. If not provided, prints to stdout.",
)
@click.option(
    "-s",
    "--size-limit",
    callback=validate_size,
    help="Maximum file size to process (e.g., 10k, 5m).",
)
@click.option(
    "-e",
    "--encoding",
    default="utf-8",
    help="File encoding.",
)
@click.option(
    "-n",
    "--lines",
    type=click.IntRange(min=1),
    default=None,
    help="Process only the first N lines.",
)
@click.option(
    "--quiet",
    "-q",
    is_flag=True,
    default=False,
    help="Suppress all output except errors.",
)
@click.option(
    "--dry-run",
    is_flag=True,
    default=False,
    help="Show what would be done without actually doing it.",
)
@click.pass_context
def process(ctx, input_path, output, size_limit, encoding, lines, quiet, dry_run):
    """Process a file with various constraints and options.

    INPUT_PATH is the path to the file to process.

    Examples:
        cli-tool process data.txt
        cli-tool process data.txt --output result.txt --lines 100
        cli-tool process data.txt --size-limit 10m --encoding latin-1
    """
    if not quiet:
        click.echo(f"Processing: {input_path}")

    file_size = os.path.getsize(input_path)
    if not quiet:
        click.echo(f"File size: {file_size:,} bytes")

    if size_limit and file_size > size_limit:
        raise click.BadParameter(
            f"File size ({file_size:,} bytes) exceeds limit ({size_limit:,} bytes).",
            ctx=ctx,
            param=None,
        )

    if dry_run:
        if not quiet:
            click.echo("[Dry run] Would process the file.")
        return

    try:
        with click.open_file(input_path, encoding=encoding, errors="replace") as f:
            if lines:
                content = "".join(f.readline() for _ in range(lines))
            else:
                content = f.read()
    except Exception as e:
        raise click.ClickException(f"Error reading file: {e}")

    if output:
        try:
            with click.open_file(output, "w", encoding=encoding) as f:
                f.write(content)
            if not quiet:
                click.echo(f"Output written to: {output}")
        except Exception as e:
            raise click.ClickException(f"Error writing file: {e}")
    else:
        click.echo(content, nl=False)

"""Generate subcommand with dynamic options and choices."""

import click
import random
import string


@click.command()
@click.argument("count", type=click.IntRange(min=1, max=1000), default=10)
@click.option(
    "--type",
    "item_type",
    type=click.Choice(["numbers", "letters", "uuid", "password"], case_sensitive=False),
    default="numbers",
    help="Type of items to generate.",
)
@click.option(
    "-l",
    "--length",
    type=click.IntRange(min=1, max=100),
    default=8,
    help="Length of generated items (applies to password/letters).",
)
@click.option(
    "-u",
    "--uppercase",
    is_flag=True,
    default=False,
    help="Use uppercase letters.",
)
@click.option(
    "--separator",
    default="\n",
    help="Separator between items (default: newline).",
)
@click.option(
    "-f",
    "--file",
    type=click.Path(writable=True),
    default=None,
    help="Write output to file instead of stdout.",
)
@click.option(
    "--seed",
    type=click.IntRange(min=0),
    default=None,
    help="Set random seed for reproducible output.",
)
@click.pass_context
def generate(ctx, count, item_type, length, uppercase, separator, file, seed):
    """Generate various types of items.

    COUNT is the number of items to generate (1-1000).

    Examples:
        cli-tool generate 5
        cli-tool generate --type password --length 12 --count 3
        cli-tool generate 10 --type uuid --separator ", "
    """
    if seed is not None:
        random.seed(seed)

    if file:
        with click.open_file(file, "w") as f:
            items = _generate_items(count, item_type, length, uppercase)
            f.write(separator.join(items) + separator)
        click.echo(f"Generated {count} {item_type} to: {file}")
    else:
        items = _generate_items(count, item_type, length, uppercase)
        click.echo(separator.join(items))


def _generate_items(count, item_type, length, uppercase):
    """Generate a list of items based on type."""
    if item_type == "numbers":
        return [str(random.randint(1, 99999)) for _ in range(count)]
    elif item_type == "letters":
        chars = string.ascii_uppercase if uppercase else string.ascii_lowercase
        return ["".join(random.choice(chars) for _ in range(length)) for _ in range(count)]
    elif item_type == "uuid":
        import uuid

        return [str(uuid.uuid4()) for _ in range(count)]
    elif item_type == "password":
        chars = string.ascii_letters + string.digits + "!@#$%^&*"
        return ["".join(random.choice(chars) for _ in range(length)) for _ in range(count)]
    return []
